// Zero-dependency mini-bundler shared by the desktop client plugins.
//
// dsh web client plugins are single self-contained files served from
// /plugins/<id>/client.js and registered through window.__ModuleLoader__.
// Host halves are real ESM (lib/*.js), but each client half ships as ONE
// bundle, so modular src/* files are wrapped here into CommonJS factories and
// concatenated — no esbuild, no network, deterministic output. Relative
// requires resolve against the module table; everything else ('react',
// primitives, …) passes through to the loader's own require.
//
// Usage (from a package's build.mjs):
//   import { buildClientBundle } from '../lib/build-client-bundle.mjs'
//   buildClientBundle({ pkgDir: <this dir>, files: ['styles.js', ..., 'index.js'] })
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import path from 'node:path'

/**
 * Bundle one client plugin's src/ modules into its client.js artifact.
 * @param pkgDir - package root (reads package.json for the bundle id + src/).
 * @param files - module file names in deterministic order.
 * @param outFile - target bundle path (default: pkgDir/client.js).
 */
export function buildClientBundle({ pkgDir, files, outFile }) {
  const srcDir = path.join(pkgDir, 'src')
  const pkg = JSON.parse(readFileSync(path.join(pkgDir, 'package.json'), 'utf8'))
  const id = pkg.name
  const target = outFile ?? path.join(pkgDir, 'client.js')

  const modules = new Map()
  for (const file of files) {
    const spec = `./${file}`
    const source = readFileSync(path.join(srcDir, file), 'utf8')
    modules.set(spec, { source, file })
  }

  // Validate every relative require up front (fail loudly, not at boot).
  for (const [spec, mod] of modules) {
    const requires = [...mod.source.matchAll(/require\((['"])(\.{1,2}\/[^'"]+)\1\)/g)].map((m) => m[2])
    for (const req of requires) {
      if (!modules.has(req)) throw new Error(`${spec}: unresolved relative require ${req}`)
    }
  }

  const factories = [...modules.entries()]
    .map(([spec, mod]) => `${JSON.stringify(spec)}: function (require, module, exports) {\n${mod.source}\n}`)
    .join(',\n')

  const bundle = `// ${id} client bundle — GENERATED by scripts/lib/build-client-bundle.mjs, do not edit.
// Modular source lives in src/; this file is the deployed artifact.
window.__ModuleLoader__.load({
\tid: ${JSON.stringify(id)},
\tfactory: (require) => {
\t\tvar __modules = {
${factories}
\t\t};
\t\tvar __cache = {};
\t\tvar __require = (spec) => {
\t\t\tif (spec.startsWith(".")) {
\t\t\t\tvar cached = __cache[spec];
\t\t\t\tif (cached !== undefined) return cached.exports;
\t\t\t\tvar factory = __modules[spec];
\t\t\t\tif (factory === undefined) throw new Error(${JSON.stringify(id)} + ": unresolved module " + spec);
\t\t\t\tvar module = { exports: {} };
\t\t\t\t__cache[spec] = module;
\t\t\t\tfactory(__require, module, module.exports);
\t\t\t\treturn module.exports;
\t\t\t}
\t\t\treturn require(spec);
\t\t};
\t\treturn __require("./index.js");
\t}
});
`

  mkdirSync(path.dirname(target), { recursive: true })
  if (existsSync(target) && readFileSync(target, 'utf8') === bundle) {
    console.log(`client bundle unchanged: ${target} (${bundle.length} bytes)`)
    return target
  }
  writeFileSync(target, bundle)
  console.log(`client bundle written: ${target} (${bundle.length} bytes)`)
  return target
}
